import{d as g,C as r,o as h,c as d,j as i,a as e,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第24章","description":"《中庸》第 24 章——至诚之道可以前知：祯祥妖孽见乎蓍龟、动乎四体；祸福将至必先知，故至诚如神。","frontmatter":{"title":"中庸·第24章","description":"《中庸》第 24 章——至诚之道可以前知：祯祥妖孽见乎蓍龟、动乎四体；祸福将至必先知，故至诚如神。","category":"guide","aliases":["第24章","中庸第24章","可以前知"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-24.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-24.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-24.md"},f=g({...m,setup(p){const o=[{id:"qianzhi",label:"至诚之道 · 可以前知",showLabel:!0,sentences:[["至诚之道，可以",{text:"前知",glossary:"qianzhi"},"。"]],note:"「至诚之道，可以前知」——至诚之道，能够预知未来。下文即举其征验。"},{id:"zhengyao",label:"国家将兴必有祯祥 · 将亡必有妖孽",showLabel:!0,sentences:[["国家将兴，必有",{text:"祯祥",glossary:"zhenxiang"},"；国家将亡，必有",{text:"妖孽",glossary:"yaonie"},"；见于",{text:"蓍龟",glossary:"shigui"},"，动乎",{text:"四体",glossary:"siti"},"。"]],note:"「国家将兴，必有祯祥；国家将亡，必有妖孽」——国家将兴会有吉兆，将亡会有凶兆；这些「见于蓍龟」（显现在占卜），「动乎四体」（流露于举动容止之间）。"},{id:"rushen",label:"祸福将至 · 故至诚如神",showLabel:!0,sentences:[["祸福将至：善，必先知之；不善，必先知之。故至诚",{text:"如神",glossary:"rushen"},"。"]],note:"「祸福将至：善，必先知之；不善，必先知之」——祸福将至，是善是恶，都能预先知道。故结一句：「至诚如神。」"}],s=[{id:"qianzhi",term:"前知",pinyin:"qián zhī",meaning:"预先知道。朱注谓所先知者皆「理之先见者也」——不是神秘预言，而是道理的先行显现。"},{id:"zhenxiang",term:"祯祥",pinyin:"zhēn xiáng",meaning:"朱注：「祯祥者，福之兆。」福的先兆。"},{id:"yaonie",term:"妖孽",pinyin:"yāo niè",meaning:"朱注：「妖孽者，祸之萌。」祸的萌动。"},{id:"shigui",term:"蓍龟",pinyin:"shī guī",meaning:"蓍：蓍草，所以筮；龟：龟甲，所以卜。古以蓍龟占问吉凶。"},{id:"siti",term:"四体",pinyin:"sì tǐ",meaning:"朱注：「谓动作威仪之间，如执玉高卑、其容俯仰之类。」即人的举止仪容。"},{id:"rushen",term:"如神",pinyin:"rú shén",meaning:"如鬼神之明。朱注：「神，谓鬼神。」"}];return(c,n)=>{const l=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第24章",tabindex:"-1"},[e("中庸·第24章 "),i("a",{class:"header-anchor",href:"#中庸·第24章","aria-label":'Permalink to "中庸·第24章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十四章说「至诚可以前知」：祯祥与妖孽既见于蓍龟，也动于人的举止；祸福将至必先知道，故「"),i("strong",null,"至诚如神"),e("」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"至诚前知 · 祯祥妖孽 · 至诚如神",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第24章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"前知",pinyin:["qián","zhī"],meaning:"预先知道。朱注谓所先知者皆「理之先见者也」——是道理的先行显现，非玄虚预言。"},{term:"祯祥",pinyin:["zhēn","xiáng"],meaning:"福之兆。"},{term:"妖孽",pinyin:["yāo","niè"],meaning:"祸之萌。"},{term:"蓍龟",pinyin:["shī","guī"],meaning:"蓍草（筮）与龟甲（卜），古之占具。"},{term:"四体",pinyin:["sì","tǐ"],meaning:"动作威仪之间（如执玉的高卑、容貌的俯仰）——人的举止里先有征兆。"},{term:"如神",pinyin:["rú","shén"],meaning:"如鬼神之明。"}]}),a(t,{items:[{term:"无私伪",pinyin:["wú","sī","wěi"],meaning:"无一毫私伪留于心目之间。"},{term:"察其几",pinyin:["chá","qí","jī"],meaning:"察见事情的几微。朱注：「惟诚之至极……乃能有以察其几焉。」看得见苗头的前提，是自己心里没有遮挡。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>至诚之道 · 可以前知</strong>：至诚之道，可以预先知道。</p><p><strong>国家将兴必有祯祥 · 将亡必有妖孽</strong>：国家将要兴盛，必有祯祥；国家将要灭亡，必有妖孽。这些既显现在蓍龟上，也表现在人的举止仪容之间。</p><p><strong>祸福将至 · 故至诚如神</strong>：祸福将要到来，善的必先知道，不善的也必先知道。所以至诚的人如神。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十四章说「至诚可以前知」，并给出前知的三种显现：<strong>祯祥</strong>（福之兆）、<strong>妖孽</strong>（祸之萌）、以及<strong>见乎蓍龟、动乎四体</strong>。最后一句是「故至诚如神」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「前知」不是神秘预言</strong>：朱注一句把它讲明白了——所先知者，皆「<strong>理之先见者也</strong>」。国将兴、将亡，都有迹可循，那些迹象是<strong>道理的先行显现</strong>。</li><li><strong>关键条件在「无私伪」</strong>：朱注说：「惟诚之至极，而<strong>无一毫私伪留于心目之间</strong>者，乃能有以察其几焉。」——苗头人人可看，但<strong>心里有私、有伪，就看不见</strong>。这一句把「诚」与前知连了起来：不是有神通，是没有遮挡。</li><li><strong>「动乎四体」是极细的观察</strong>：朱注举「执玉高卑、其容俯仰」——一个人的举手投足，先泄露出内在的状态。</li><li><strong>承上两章而变调</strong>：第 22 章讲至诚的「力量」（尽性参天），第 23 章讲致曲的「展开」（形著明动变化），本章讲至诚的「明」（前知如神）。<strong>三章合观，是至诚的体、用、明。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>把「前知」还原为察几</strong>：任何变化都有苗头；训练自己看苗头，而不是等结果。</li><li><strong>检查自己的「遮挡」</strong>：看不见苗头，往往不是眼力不够，而是<strong>心里有私伪</strong>——不愿看见。</li><li><strong>观察四体</strong>：一个人的真实状态，常在他自己没注意的举止里。</li><li><strong>不神化</strong>：这一章不是占卜教程，而是说「至诚者明」。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>至诚的人，可以<strong>预先知道</strong>。</p><p>国家要兴盛，有祯祥；国家要灭亡，有妖孽——这些既显在蓍草龟甲上，也动在人的举止仪容之间。祸福要来，善的、不善的，都能先知道。所以说「<strong>至诚如神</strong>」。</p><p>但朱熹把这句话讲得很实在：先知的不是玄机，是「<strong>理之先见</strong>」——事情变化之前，道理已经在显形。而能看见的条件只有一个：<strong>自己心里没有私、没有伪，没有遮挡。</strong></p><p>苗头本来就在那里。看得见看不见，差的是心境。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「理之先见」——最近有没有一件事，苗头其实早就出现，我没看见？</li><li>「无一毫私伪留于心目之间」——我看不见，是眼力不够，还是不愿看见？</li><li>「动乎四体」——我自己的状态，有没有先从举止里漏出来过？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-23">中庸·第23章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-25">中庸·第25章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{b as __pageData,f as default};
